namespace ghidra.app.plugin.core.symboltree.actions;

using org.apache.commons.lang3;

using docking;
using docking.action;
using docking.action;
using docking.tool;
using ghidra.app.cmd.label;
using ghidra.app.context;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util;
using ghidra.util;
using ghidra.util.task;

public class SetSymbolPrimaryAction : DockingAction {

	private static readonly string NAME = "Set Label Primary";

	public SetSymbolPrimaryAction() : base(NAME, ToolConstants.SHARED_OWNER)
    {

		// Note: the group '2' is that of the PinSymbolAction.  That group seems like a nice place.
		setPopupMenuData(new MenuData(new string[] { "Set Primary" }, "2"));
		setHelpLocation(new HelpLocation("SymbolTablePlugin", "Set_Primary"));
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {

		if (!(context is ProgramSymbolActionContext psac)) {
			return false;
		}

		int n = psac.getSymbolCount();
		if (n != 1) {
			return false;
		}

		Symbol s = psac.getFirstSymbol();
		return !s.isPrimary();
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		ProgramSymbolActionContext psac = (ProgramSymbolActionContext) context;
		Symbol s = psac.getFirstSymbol();
		Namespace ns = s.getParentNamespace();
		string name = s.getName();
		Address addr = s.getAddress();
		SetLabelPrimaryCmd cmd = new SetLabelPrimaryCmd(addr, name, ns);
		TaskLauncher.launchModal(NAME, () => {

			Program p = psac.getProgram();
			p.withTransaction(NAME, () => {
				cmd.applyTo(p);
			});

		});

		string errorMessage = cmd.getStatusMsg();
		if (!StringUtils.isBlank(errorMessage)) {
			Msg.showError(getClass(), null, "Unable to Set Label Primary", errorMessage);
		}
	}

}
